select (ROW_NUMBER() OVER(order by ins_dt desc)) AS "rownum",
site_sq as "siteSq", site_nm as "siteNm", scco_cd as "sccoCd", user_sq as "userSq", user_nm as "userNm", user_lv as "rollCd", case user_lv when '1' then '검침원사용자' when '5' then '타사사용자' when '7' then '준마스터사용자' when '9' then '마스터사용자' end "useCdStr", user_id as "userId", user_pwd as "userPwd", email as "email", phone as "custPhone", remark as "remark", site_path as "sitePath", site_lv as "siteLv", ins_dt as "insDt" from vi_m1_sv_login where 1=1 and use_cd = '1'
and user_id = #{userId}

mapper.select:
select site_sq as "siteSq", blk_sq as "blkSq", up_blk_sq as "parSq", blk_cd as "blkCd", blk_nm as "blkNm", "level" as "level", leap as "leap" from vi_m1_sv_block_list where site_sq = #{siteSq}
and blk_sq in ( select blk_sq from fn_prj_blockes(#{upBlkSq}::integer, #{lv}::integer) )
order by blk_path

WITH filtered_points AS ( SELECT b.point_sq, b.blk_name, b.use_type, b.pipe_dia, b.admin_id, b.cust_nm, b.addr_new, substr(b.read_opr,1,3) as read_opr, b.site_sq, b.dev_no, b.meter_no, ROW_NUMBER() OVER(
ORDER BY "${sortField}" ${sortOrder}
ORDER BY b.point_sq
) as rn, COUNT(*) OVER() as total_count FROM vi_m1_sv_point_list b
LEFT JOIN LATERAL ( SELECT m.ami_err_code, m.meas_dt as lr_meas_dt FROM client_meas_raw m WHERE m.point_sq = b.point_sq AND m.meas_dt >= CURRENT_DATE - 3 ORDER BY m.meas_dt DESC LIMIT 1 ) lr_f ON TRUE
WHERE b.use_cd = '1'
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and b.site_sq = #{siteSq}::integer
and b.blk_sq in ( select blk_sq from fn_prj_blockes(#{upBlkSq}::integer, #{lv}::integer) )
and b.blk_sq = #{blkSq}::integer
and b.blk_sq IS NULL
and b.company_sq = #{comSq}::integer
and b.company_sq IS NULL
and b.ami_type = #{amiType}
and b.ami_type IS NULL
and b.read_opr = #{readOpr}
and b.read_opr IS NULL
and b.check_day = #{chkDay}
and b.check_day IS NULL
and b.use_type = #{useType}
and b.use_type IS NULL
and b.set_years = #{setYears}
and b.set_years IS NULL
and b.pipe_dia = #{pipeDia}::numeric
and b.pipe_dia is null
and (lr_f.lr_meas_dt IS NULL OR lr_f.lr_meas_dt < CURRENT_DATE - 3)
and lr_f.lr_meas_dt IS NOT NULL and lr_f.lr_meas_dt >= CURRENT_DATE - 3 and substring(lr_f.ami_err_code, 1, 1) = '1'
and lr_f.lr_meas_dt IS NOT NULL and lr_f.lr_meas_dt >= CURRENT_DATE - 3 and (lr_f.ami_err_code IS NULL OR substring(lr_f.ami_err_code, 1, 1) != '1')
and b.point_sq = #{pointSq}
AND b.waterleak_flag = #{leakFg}
AND b.send_cd = #{sendCd}
and b.cust_nm like '%' || #{cust_nm} || '%'
and b.admin_id like '%' || #{admin_no} || '%'
and b.tap_gb = #{tap_gb}
and b.bungu_cd = #{bungu_cd}
and b.site_sq in ( select site_sq from fn_prj_sites(#{addr_1} :: integer, '4' :: integer) )
and (b.addr_old like '%' || #{addr} || '%' or b.addr_new like '%' || #{addr} || '%')
), paged_points AS ( SELECT * FROM filtered_points WHERE rn > ${rnBottom} AND rn <= ${rnTop} ), day_pivot AS ( SELECT d.point_sq, sum(case when extract(day from d.meas_dt) = 1 then d.accu_iv end) as iv_d1, sum(case when extract(day from d.meas_dt) = 2 then d.accu_iv end) as iv_d2, sum(case when extract(day from d.meas_dt) = 3 then d.accu_iv end) as iv_d3, sum(case when extract(day from d.meas_dt) = 4 then d.accu_iv end) as iv_d4, sum(case when extract(day from d.meas_dt) = 5 then d.accu_iv end) as iv_d5, sum(case when extract(day from d.meas_dt) = 6 then d.accu_iv end) as iv_d6, sum(case when extract(day from d.meas_dt) = 7 then d.accu_iv end) as iv_d7, sum(case when extract(day from d.meas_dt) = 8 then d.accu_iv end) as iv_d8, sum(case when extract(day from d.meas_dt) = 9 then d.accu_iv end) as iv_d9, sum(case when extract(day from d.meas_dt) = 10 then d.accu_iv end) as iv_d10, sum(case when extract(day from d.meas_dt) = 11 then d.accu_iv end) as iv_d11, sum(case when extract(day from d.meas_dt) = 12 then d.accu_iv end) as iv_d12, sum(case when extract(day from d.meas_dt) = 13 then d.accu_iv end) as iv_d13, sum(case when extract(day from d.meas_dt) = 14 then d.accu_iv end) as iv_d14, sum(case when extract(day from d.meas_dt) = 15 then d.accu_iv end) as iv_d15, sum(case when extract(day from d.meas_dt) = 16 then d.accu_iv end) as iv_d16, sum(case when extract(day from d.meas_dt) = 17 then d.accu_iv end) as iv_d17, sum(case when extract(day from d.meas_dt) = 18 then d.accu_iv end) as iv_d18, sum(case when extract(day from d.meas_dt) = 19 then d.accu_iv end) as iv_d19, sum(case when extract(day from d.meas_dt) = 20 then d.accu_iv end) as iv_d20, sum(case when extract(day from d.meas_dt) = 21 then d.accu_iv end) as iv_d21, sum(case when extract(day from d.meas_dt) = 22 then d.accu_iv end) as iv_d22, sum(case when extract(day from d.meas_dt) = 23 then d.accu_iv end) as iv_d23, sum(case when extract(day from d.meas_dt) = 24 then d.accu_iv end) as iv_d24, sum(case when extract(day from d.meas_dt) = 25 then d.accu_iv end) as iv_d25, sum(case when extract(day from d.meas_dt) = 26 then d.accu_iv end) as iv_d26, sum(case when extract(day from d.meas_dt) = 27 then d.accu_iv end) as iv_d27, sum(case when extract(day from d.meas_dt) = 28 then d.accu_iv end) as iv_d28, sum(case when extract(day from d.meas_dt) = 29 then d.accu_iv end) as iv_d29, sum(case when extract(day from d.meas_dt) = 30 then d.accu_iv end) as iv_d30, sum(case when extract(day from d.meas_dt) = 31 then d.accu_iv end) as iv_d31 FROM client_meas_day d WHERE d.point_sq IN (SELECT point_sq FROM paged_points) AND d.meas_dt >= date_trunc('month', to_date(#{baseDate}, 'yyyy-mm-dd')) AND d.meas_dt < date_trunc('month', to_date(#{baseDate}, 'yyyy-mm-dd')) + INTERVAL '1 month' GROUP BY d.point_sq ) SELECT p.rn as "rownum", p.rn as "rownum_", p.point_sq as "pointSq", p.blk_name as "blkNm", p.use_type as "useType", p.pipe_dia as "pipeDia", p.admin_id as "adminId", p.cust_nm as "custName", p.addr_new as "addr", p.read_opr as "readOpr", p.site_sq as "siteSq", p.dev_no as "devNo", p.meter_no as "meterNo", dp.iv_d1 as "D01", dp.iv_d2 as "D02", dp.iv_d3 as "D03", dp.iv_d4 as "D04", dp.iv_d5 as "D05", dp.iv_d6 as "D06", dp.iv_d7 as "D07", dp.iv_d8 as "D08", dp.iv_d9 as "D09", dp.iv_d10 as "D10", dp.iv_d11 as "D11", dp.iv_d12 as "D12", dp.iv_d13 as "D13", dp.iv_d14 as "D14", dp.iv_d15 as "D15", dp.iv_d16 as "D16", dp.iv_d17 as "D17", dp.iv_d18 as "D18", dp.iv_d19 as "D19", dp.iv_d20 as "D20", dp.iv_d21 as "D21", dp.iv_d22 as "D22", dp.iv_d23 as "D23", dp.iv_d24 as "D24", dp.iv_d25 as "D25", dp.iv_d26 as "D26", dp.iv_d27 as "D27", dp.iv_d28 as "D28", dp.iv_d29 as "D29", dp.iv_d30 as "D30", dp.iv_d31 as "D31", p.total_count as "totalCount", ${rnTop} / (${rnTop} - ${rnBottom}) as "pageNo", ${rnTop} - ${rnBottom} as "pageSize" FROM paged_points p LEFT JOIN day_pivot dp ON p.point_sq = dp.point_sq ORDER BY p.rn

with tb_t as (
select b.point_sq, a.raw_cnt from vi_m1_sv_meas_day a right join ( select b.* from vi_m1_sv_point_list b
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and b.site_sq = #{siteSq}::integer
) b on b.point_sq = a.point_sq
and a.meas_dt >= date_trunc('days', now()) - (#{day}::text || ' days')::interval and a.meas_dt < date_trunc('days', now())
), tb_total_t as ( select point_sq, count(*) cnt from tb_t where raw_cnt is not null group by point_sq ), tb_result_t as ( select a.point_sq, case when a.t_ratio - MOD(a.t_ratio::integer, 10) < 80 or t_ratio is null then 0 else a.t_ratio - MOD(a.t_ratio::integer, 10) end t_ratio from (
select point_sq, trunc((sum(raw_cnt)::float/(#{day}*24)::float)*100) t_ratio from tb_t where raw_cnt is not null group by point_sq
) a ), tb_total_d as ( select point_sq, count(*) cnt from tb_t group by point_sq ), tb_result_d as ( select point_sq, case when d_ratio < 80 or d_ratio is null then 0 else d_ratio end d_ratio from (
select a.point_sq, trunc(b.not_null_cnt::float / a.cnt::float) * 100 d_ratio from tb_total_d a left join ( select point_sq, count(*) not_null_cnt from tb_t where raw_cnt is not null group by point_sq ) b on b.point_sq = a.point_sq
) a ) select * from ( select d_ratio as ratio, count(*) cnt, '1'::text as type, 2::integer as indexOf from tb_result_d group by d_ratio union all select null as ratio, count(*), '0'::text as type, 2::integer as indexOf from tb_total_d a union all select t_ratio as ratio, count(*) cnt, '1'::text as type, 1::integer as indexOf from tb_result_t group by t_ratio union all select null as ratio, count(*), '0'::text as type, 1::integer as indexOf from tb_total_t ) a
a.indexOf = #{indexOf}

