mapper.sql:
with tb_t as (
select point_sq, max(flow_max) flow_max from vi_m1_sv_meas_day where meas_dt > now() - (#{noUseObDays}::text || ' days')::interval and meas_dt <= now() GROUP BY point_sq
) select (ROW_NUMBER() OVER()) AS "rownum", a.point_sq as "pointSq", a.site_nm0 as "siteNm0", a.site_nm as "siteNm", a.admin_id as "adminId", -- a.cust_nm as "custNm", a.addr_new as "addrNew", a.blk_sq as "blkSq", -- 블럭 Sq a.blk_name as "blkNm", -- 블럭 이름 a.pipe_dia as "pipeDia", -- 관경 a.use_type as "useType", -- 업종 (가정용/일반용/학교용) a.read_opr as "readOpr", -- 검침원 a.dev_no as "devNo", a.meter_no as "meterNo", a.flag from ( select a.*,
CASE
WHEN a.pipe_dia > 0 and a.pipe_dia <= 15 and b.flow_max < c.q1_15 THEN '1' WHEN a.pipe_dia > 15 and a.pipe_dia <= 20 and b.flow_max < c.q1_20 THEN '1' WHEN a.pipe_dia > 20 and a.pipe_dia <= 25 and b.flow_max < c.q1_25 THEN '1' WHEN a.pipe_dia > 25 and a.pipe_dia <= 32 and b.flow_max < c.q1_32 THEN '1' WHEN a.pipe_dia > 32 and a.pipe_dia <= 40 and b.flow_max < c.q1_40 THEN '1' WHEN a.pipe_dia > 40 and a.pipe_dia <= 50 and b.flow_max < c.q1_50 THEN '1' WHEN a.pipe_dia > 50 and a.pipe_dia <= 75 and b.flow_max < c.q1_75 THEN '1' WHEN a.pipe_dia > 75 and a.pipe_dia <= 100 and b.flow_max < c.q1_100 THEN '1' WHEN a.pipe_dia > 100 and a.pipe_dia <= 150 and b.flow_max < c.q1_150 THEN '1' WHEN a.pipe_dia > 150 and a.pipe_dia <= 200 and b.flow_max < c.q1_200 THEN '1' WHEN a.pipe_dia > 200 and a.pipe_dia <= 250 and b.flow_max < c.q1_250 THEN '1' WHEN a.pipe_dia > 250 and b.flow_max < c.q1_250 THEN '1'
ELSE '0' END flag from vi_m1_sv_point_list a left join tb_t b on b.point_sq = a.point_sq left join tb_m1_waterleak_setting c on c.site_sq = a.site_sq
and a.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and a.site_sq = #{siteSq}::integer
and a.blk_sq in ( select blk_sq from fn_prj_blockes(#{upBlkSq}::integer, #{lv}::integer) )
and a.blk_sq = #{blkSq}::integer
and a.blk_sq IS NULL
and a.company_sq = #{comSq}::integer
and a.company_sq IS NULL
and a.ami_type = #{amiType}
and a.ami_type IS NULL
and a.read_opr = #{readOpr}
and a.read_opr IS NULL
and a.check_day = #{chkDay}
and a.check_day IS NULL
and a.use_type = #{useType}
and a.use_type IS NULL
and a.set_years = #{setYears}
and a.set_years IS NULL
and a.pipe_dia = #{pipeDia}::numeric
and a.pipe_dia is null
and a.use_cd = #{useCd}
and a.use_cd = '1'
and position('1' in a.stat_cd) = #{statCd}::integer
and a.point_sq = #{pointSq}
( a.cust_nm like '%${searchParam}%' OR a.admin_id like '%${searchParam}%' OR a.addr_new like '%${searchParam}%'
)
( a.cust_nm like '%${searchParam}%' OR a.admin_id like '%${searchParam}%' OR a.addr_new like '%${searchParam}%'
)
( a.dev_no like '%${searchParam}%' OR a.meter_no like '%${searchParam}%' )
) a where a.flag = '1'

select a.point_sq as "pointSq", b.site_nm0 as "siteNm0", b.site_nm as "siteNm", b.admin_id as "adminId", b.cust_nm as "custNm", b.addr_new as "addrNew", b.dev_no as "devNo", b.meter_no as "meterNo", b.blk_sq as "blkSq", -- 블럭 Sq b.blk_name as "blkNm", -- 블럭 이름 b.pipe_dia as "pipeDia", -- 관경 b.use_type as "useType", -- 업종 (가정용/일반용/학교용) b.read_opr as "readOpr", -- 검침원
a.std1 as "q1", a.std2 as "q2", a.iqr as "iqr", a.iqr_x3_0 as "iqr30", a.iqr_x1_5 as "iqr15", a.term_cv as "termCv", a.stat_cd as "statCd", a.meas_dt as "measDt", to_char(a.meas_dt, 'yyyy-mm-dd') as "measDtStr", b.site_sq, b.site_nm from fn_meas_waterleak_iqr(#{obDays}::int, #{rDays}::int) a join vi_m1_sv_point_list b on a.point_sq = b.point_sq
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
