and b.point_sq = #{pointSq}
( b.cust_nm like '%${searchParam}%' OR b.admin_id like '%${searchParam}%' OR b.addr_new like '%${searchParam}%'
)
( b.cust_nm like '%${searchParam}%' OR b.admin_id like '%${searchParam}%' OR b.addr_new like '%${searchParam}%'
)
( b.dev_no like '%${searchParam}%' OR b.meter_no like '%${searchParam}%' )

select (ROW_NUMBER() OVER()) AS "rownum", b.blk_name as "blkNm", b.use_type as "useType", b.pipe_dia as "pipeDia", b.admin_id as "adminId", b.cust_nm as "custName", b.read_opr as "readOpr", b.point_sq as "pointSq", b.site_sq as "siteSq", b.dev_no as "devNo", b.meter_no as "meterNo", a.f_m as "flowMinPoint", a.iv_d1 as "D01", a.iv_d2 as "D02", a.iv_d3 as "D03", a.iv_d4 as "D04", a.iv_d5 as "D05", a.iv_d6 as "D06", a.iv_d7 as "D07", a.iv_d8 as "D08", a.iv_d9 as "D09", a.iv_d10 as "D10", a.iv_d11 as "D11", a.iv_d12 as "D12", a.iv_d13 as "D13", a.iv_d14 as "D14", a.iv_d15 as "D15", a.iv_d16 as "D16", a.iv_d17 as "D17", a.iv_d18 as "D18", a.iv_d19 as "D19", a.iv_d20 as "D20", a.iv_d21 as "D21", a.iv_d22 as "D22", a.iv_d23 as "D23", a.iv_d24 as "D24", a.iv_d25 as "D25", a.iv_d26 as "D26", a.iv_d27 as "D27", a.iv_d28 as "D28", a.iv_d29 as "D29", a.iv_d30 as "D30", a.iv_d31 as "D31", a.iv_d32 as "D32" from fn_meas_raw_for_day_flow_min(to_date(#{baseDate}, 'yyyy-mm-dd')) a right outer join vi_m1_sv_point_list b on a.point_sq = b.point_sq
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
