and b.use_cd = '1'
and position('1' in b.stat_cd) = #{statCd}::integer
and b.point_sq = #{pointSq}
( b.cust_nm like '%${searchParam}%' OR b.admin_id like '%${searchParam}%' OR b.addr_new like '%${searchParam}%'
)
( b.cust_nm like '%${searchParam}%' OR b.admin_id like '%${searchParam}%' OR b.addr_new like '%${searchParam}%'
)
( b.dev_no like '%${searchParam}%' OR b.meter_no like '%${searchParam}%' )

with tb_target as (
select cast(extract( day from date_trunc('day', now()) - date_trunc('day', meas_dt)) as int) / 7 dw_no, a.* from fn_tb_meas_point_his_day_mov(#{pointSq}, to_date(#{begDate}, 'yyyy-mm-dd'), to_date(#{endDate}, 'yyyy-mm-dd') ) a
), tb_cnt as ( select count(*)/7 cnt, point_sq from tb_target group by point_sq ), tb_week as ( select a.* from tb_target a join tb_cnt b on b.point_sq = a.point_sq where
a.meas_dt > date_trunc('day', now()) - make_interval(days => (b.cnt::integer * 7)) and a.meas_dt <= date_trunc('day', now())
) select a.point_sq as "pointSq", a.meas_dt as "measDt", b.sum_term as"termCv" from (
select a.point_sq, a.dw_no, max(a.meas_dt) meas_dt from tb_week a group by a.point_sq, a.dw_no
) a join (
select a.point_sq, a.dw_no, sum(a.term_cv) sum_term from tb_week a group by a.point_sq, a.dw_no
) b on b.point_sq = a.point_sq and b.dw_no = a.dw_no order by a.meas_dt desc

with day_raw as ( select a.point_sq, a.meas_dt, a.last_dt, a.raw_cnt, ((CASE WHEN substr(COALESCE(a.stat_cd, '1')::text, 1, 1) = '1' THEN '1' ELSE '0' END || CASE WHEN a.raw_cnt IS NULL OR a.raw_cnt = 0 THEN '1' ELSE '0' END || substring(COALESCE(a.stat_cd, '00000000')::text, 2, 7)))::char(9) AS stat_cd, a.accu_iv, a.accu_cv, GREATEST(a.accu_iv - lag(a.accu_iv) OVER (PARTITION BY a.point_sq ORDER BY a.meas_dt), 0) as term_cv, CASE WHEN a.accu_iv < lag(a.accu_iv) OVER (PARTITION BY a.point_sq ORDER BY a.meas_dt) THEN a.adjst_os ELSE 0 END as adjst_os, a.temperature from client_meas_day a where a.point_sq = #{pointSq}::integer
and a.meas_dt >= (to_date(#{begDate}, 'yyyy-mm-dd') - interval '30 day')::date and a.meas_dt <= to_date(#{endDate}, 'yyyy-mm-dd')
), day_base as ( select point_sq, meas_dt, last_dt, raw_cnt, stat_cd, accu_iv, accu_cv, term_cv, adjst_os, avg(term_cv) over w1 as term_cv_1d, avg(term_cv) over w2 as term_cv_7d, avg(term_cv) over w3 as term_cv_30d, avg(temperature) over w1 as temperature from day_raw window w1 as (partition by point_sq order by meas_dt rows between 1 preceding and 1 preceding), w2 as (partition by point_sq order by meas_dt rows between 7 preceding and current row), w3 as (partition by point_sq order by meas_dt rows between 30 preceding and current row) ), main_data as ( select point_sq, meas_dt, last_dt, raw_cnt, stat_cd, accu_iv, accu_cv, adjst_os, term_cv, trunc(term_cv_1d, 3) as term_cv_1d, trunc(term_cv_7d, 3) as term_cv_7d, trunc(term_cv_30d, 3) as term_cv_30d, temperature from day_base
where meas_dt >= (to_date(#{begDate}, 'yyyy-mm-dd') - interval '1 day')
), /* 누수의심 계산 - client_meas_raw에서 accu_iv 차이로 계산 */ raw_term_for_leak AS ( SELECT point_sq, meas_dt, GREATEST(accu_iv - lag(accu_iv) OVER (PARTITION BY point_sq ORDER BY meas_dt), 0) AS real_term_cv FROM client_meas_raw WHERE point_sq = #{pointSq}::integer AND meas_dt >= (SELECT MIN(meas_dt) - interval '24 hours' FROM main_data) AND meas_dt <= (SELECT MAX(meas_dt) FROM main_data) ), leak_suspects as ( select distinct rwt.point_sq, md.meas_dt, '누수의심' as leak_status from main_data md cross join lateral ( select rwt.point_sq from raw_term_for_leak rwt join tb_m1_info_point p on p.point_sq = rwt.point_sq join tb_m1_info_customer c on c.cust_sq = p.cust_sq where rwt.point_sq = md.point_sq and rwt.real_term_cv is not null and rwt.point_sq not in (select point_sq from tb_m1_waterleak_hide_setting) and rwt.meas_dt between md.meas_dt - interval '24 hours' and md.meas_dt and p.use_cd = '1' group by rwt.point_sq, c.pipe_diameter, c.business_name having min(rwt.real_term_cv) >= COALESCE( (SELECT leak_rule FROM tb_m1_rule_waterleak WHERE business_name = c.business_name AND pipe_diameter <= c.pipe_diameter ORDER BY pipe_diameter DESC LIMIT 1), (SELECT leak_rule FROM tb_m1_rule_waterleak WHERE business_name = '기타' AND pipe_diameter <= c.pipe_diameter ORDER BY pipe_diameter DESC LIMIT 1) ) ) rwt ) select (ROW_NUMBER() OVER()) AS "rownum", md.point_sq as "pointSq", md.meas_dt as "measDt", to_char(md.meas_dt, 'YYYY-MM-DD') as "measDtStr", md.last_dt as "lastDt", md.raw_cnt as "rawCnt", md.stat_cd as "statCd", coalesce(ls.leak_status, '-') as "leakSuspect", md.accu_iv as "accuIv", md.accu_cv as "accuCv", md.adjst_os as "adjstV", md.term_cv as "termCv", md.term_cv_1d as "termCv_1d", md.term_cv_7d as "termCv_7d", md.term_cv_30d as "termCv_30d", md.temperature from main_data md left join leak_suspects ls on ls.point_sq = md.point_sq and ls.meas_dt = md.meas_dt order by md.meas_dt desc

